CREATE OR REPLACE FUNCTION public.fn_diamond_game_pay_diamonds(p_owner uuid, p_user uuid, p_amount integer, p_note text, p_reference text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_res jsonb;
BEGIN
  IF p_amount <= 0 THEN RETURN; END IF;
  IF p_owner IS NULL THEN
    RAISE EXCEPTION 'diamond games: no owner to pay the diamond prize %', p_reference;
  END IF;
  v_res := public.add_diamonds_to_balance(p_owner, -p_amount, 'transfer', p_note, p_reference || ':host', p_user);
  IF COALESCE((v_res->>'success')::boolean, false) = false THEN
    RAISE EXCEPTION 'diamond games: the host owner could not pay the diamond prize %: %', p_reference, v_res->>'error';
  END IF;
  v_res := public.add_diamonds_to_balance(p_user, p_amount, 'transfer', p_note, p_reference, p_owner);
  IF COALESCE((v_res->>'success')::boolean, false) = false THEN
    RAISE EXCEPTION 'diamond games: the diamond prize could not be credited %: %', p_reference, v_res->>'error';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.fn_diamond_spin_settle_day(p_owner uuid, p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE bucket public.diamond_spin_days;paid jsonb;notice uuid:=gen_random_uuid();target_club uuid;
 total numeric;movement_total bigint;v_net integer;v_reference text;
 v_bps integer:=public.fn_diamond_spin_profit_burn_bps();v_burn bigint;v_credit integer;v_burn_op text;v_supply numeric;
BEGIN
 IF NOT public.fn_is_service_context() THEN RAISE EXCEPTION 'Daily Diamond Settlement Is Service Managed' USING ERRCODE='42501'; END IF;
 IF p_owner IS NULL OR p_day IS NULL OR p_day>=(clock_timestamp() AT TIME ZONE 'America/Chicago')::date THEN
  RAISE EXCEPTION 'Only A Closed Chicago Business Day Can Settle'; END IF;
 PERFORM 1 FROM public.profiles WHERE id=p_owner FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'The Diamond Spin Owner Wallet Is Missing'; END IF;
 SELECT * INTO bucket FROM public.diamond_spin_days WHERE owner_id=p_owner AND day=p_day FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',true,'empty',true,'day',p_day); END IF;
 IF bucket.status='settled' THEN RETURN jsonb_build_object('ok',true,'replayed',true,'day',p_day,'net_diamonds',bucket.settled_net,
  'profit_burn',bucket.profit_burn,'profit_burn_bps',bucket.profit_burn_bps,'credited_net',bucket.credited_net,
  'wallet_transaction_id',bucket.wallet_transaction_id,'notification_id',bucket.notification_id); END IF;
 IF public.fn_platform_frozen() THEN RAISE EXCEPTION 'Diamond Settlement Is Paused For Maintenance'; END IF;
 SELECT COALESCE(sum(amount),0),count(*) INTO total,movement_total FROM public.diamond_spin_movements WHERE owner_id=p_owner AND day=p_day;
 IF total IS DISTINCT FROM bucket.pending_diamonds OR movement_total IS DISTINCT FROM bucket.movement_count THEN
  RAISE EXCEPTION 'Diamond Spin Statement Does Not Match Its Movements'; END IF;
 v_net:=bucket.pending_diamonds::integer;
 v_burn:=public.fn_diamond_spin_profit_burn(v_net,v_bps);
 v_credit:=v_net-v_burn;
 v_reference:='diamond-spin-day:'||p_owner||':'||p_day;
 v_burn_op:='diamond-spin-burn:'||p_owner||':'||p_day;
 -- Release exactly this day's balance before the canonical wallet writer checks
 -- other days' reserves. All state, register, wallet, statement and notification
 -- commit together. A placeholder transaction ID is replaced below in the same
 -- transaction; no externally visible half-settlement is possible.
 UPDATE public.diamond_spin_days SET status='settling',pending_diamonds=0,settled_net=v_net,
  profit_burn_bps=v_bps,profit_burn=v_burn,
  settled_at=clock_timestamp(),wallet_transaction_id=CASE WHEN v_credit<>0 THEN notice END,notification_id=notice
  WHERE owner_id=p_owner AND day=p_day;
 IF v_burn>0 THEN
  -- The platform's share of a profitable day leaves custody and reaches no
  -- wallet: it is retired in the canonical Mint register, exactly as consumed
  -- inventory already is, so the supply falls by the burn and nothing is burned
  -- by omission. UNIQUE(op_id) makes a second burn for the same day impossible.
  SELECT public.fn_ca_mint_supply('diamonds')-v_burn INTO v_supply;
  INSERT INTO public.ca_mint_ledger(op_id,action,asset,holder_type,holder_id,holder_label,amount,
   balance_before,balance_after,supply_after,reason,performed_by,performed_by_label)
  VALUES(v_burn_op,'burn','diamonds','player',p_owner,
   COALESCE((SELECT username FROM public.profiles WHERE id=p_owner),p_owner::text),v_burn,
   v_net,v_credit,v_supply,format('Diamond Spins Daily Profit Burn (%s%%) For %s',v_bps/100,p_day),
   auth.uid(),COALESCE((SELECT username FROM public.profiles WHERE id=auth.uid()),auth.uid()::text));
 END IF;
 IF v_credit<>0 THEN
  paid:=public.add_diamonds_to_balance(p_owner,v_credit,'transfer',
    'Diamond Spins Daily Net Settlement For '||p_day,v_reference,p_owner);
  IF COALESCE((paid->>'success')::boolean,false) IS NOT TRUE THEN
   RAISE EXCEPTION 'Diamond Spin Settlement Failed: %',COALESCE(paid->>'error','unknown'); END IF;
 END IF;
 SELECT club_id INTO target_club FROM public.diamond_spin_movements WHERE owner_id=p_owner AND day=p_day ORDER BY created_at,id LIMIT 1;
 -- One statement a day, in the app only: '_push' keeps it out of push_outbox
 -- (owner ruling 2026-09-21 R17). The ledger is the record.
 INSERT INTO public.notifications(id,user_id,type,title,message,data,action_url,link)
 VALUES(notice,p_owner,'diamond_spin_settlement','Diamond Spins Daily Statement',
  format('%s Diamonds Net For %s. Platform Burn (%s%%): %s. Credited To Your Wallet: %s. Entries: %s. Prizes And Inventory: %s.',v_net,p_day,v_bps/100,v_burn,v_credit,
   bucket.entry_diamonds+bucket.bonus_diamonds+bucket.mint_entry_diamonds,
   bucket.diamond_prizes+bucket.throwables+bucket.time_banks+bucket.rabbit_hunts+bucket.other_expenses),
  jsonb_build_object('day',p_day,'timezone','America/Chicago','net_diamonds',v_net,'profit_burn',v_burn,'profit_burn_bps',v_bps,
   'credited_net',v_credit,'club_id',target_club,'wallet_transaction_id',paid->>'transaction_id','burn_op_id',CASE WHEN v_burn>0 THEN v_burn_op END,
   '_push','ledger_only'),
  '/hub/club-arena/clubs/'||target_club||'/diamond-games-operations',
  '/hub/club-arena/clubs/'||target_club||'/diamond-games-operations');
 -- The legal open-to-settled transition is performed once by the actual writer;
 -- finalized receipts are never updated afterward (trigger recognizes this local phase).
 UPDATE public.diamond_spin_days SET status='settled',wallet_transaction_id=(paid->>'transaction_id')::uuid
 WHERE owner_id=p_owner AND day=p_day;
 RETURN jsonb_build_object('ok',true,'day',p_day,'net_diamonds',v_net,'profit_burn',v_burn,'profit_burn_bps',v_bps,'credited_net',v_credit,
  'wallet_transaction_id',paid->>'transaction_id','notification_id',notice);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_jackpot_pay(p_table_id uuid, p_hand_number bigint, p_pot numeric, p_players_dealt integer, p_loser_user_id uuid, p_winner_user_id uuid, p_table_user_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pool uuid; v_ref text; v_bb numeric; v_variant text; v_scope text;
  v_main bigint; v_pct numeric; v_paid bigint; v_shares text;
  v_loser bigint; v_winner bigint; v_table_total bigint;
  v_others uuid[]; v_n integer; v_each bigint; v_remainder bigint;
  v_rec record; v_credit jsonb; v_key text; v_inserted integer;
  v_paid_out bigint := 0; v_legs jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.fn_ca_diamond_economic_on('bbj_enabled') THEN
    RAISE EXCEPTION 'diamond_bad_beat_jackpot_not_open' USING ERRCODE = '55000';
  END IF;
  IF p_loser_user_id IS NULL OR p_winner_user_id IS NULL
     OR p_loser_user_id = p_winner_user_id THEN
    RAISE EXCEPTION 'diamond_jackpot_needs_a_loser_and_a_winner' USING ERRCODE = '23514';
  END IF;

  SELECT t.big_blind, t.game_variant INTO v_bb, v_variant
    FROM public.tables t JOIN public.clubs c ON c.id = t.club_id
   WHERE t.id = p_table_id AND c.asset = 'diamonds' AND c.is_platform IS TRUE
     AND c.union_id IS NULL AND t.union_id IS NULL AND t.tournament_id IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'diamond_plain_cash_table_required' USING ERRCODE = '23514';
  END IF;
  v_scope := public.fn_poker_diamond_jackpot_stake_scope(v_bb);

  -- B16: a game with no jackpot can never win one.
  IF NOT public.fn_poker_diamond_jackpot_game_qualifies(v_variant) THEN
    RAISE EXCEPTION 'diamond_jackpot_game_has_no_jackpot:%', v_variant USING ERRCODE = '23514';
  END IF;
  -- B15's symmetry: a stake that drops nothing can never hit.
  IF public.fn_ca_diamond_economic('bbj_drop_per_hand', v_scope) <= 0 THEN
    RAISE EXCEPTION 'diamond_jackpot_stake_drops_nothing:%', v_scope USING ERRCODE = '23514';
  END IF;
  -- B17, the payout gates. The pot floor is a payout floor and only ever that.
  IF p_players_dealt IS NULL
     OR p_players_dealt < public.fn_ca_diamond_economic('bbj_min_dealt_in') THEN
    RAISE EXCEPTION 'diamond_jackpot_too_few_dealt_in:%', p_players_dealt USING ERRCODE = '23514';
  END IF;
  -- bbj_min_pot is recorded in DIAMONDS, per stake: ten big blinds of a
  -- whole-Diamond blind is a whole number of Diamonds, so the floor is stored
  -- as the figure the door compares against rather than as a multiplier the
  -- door would have to apply.
  IF p_pot IS NULL
     OR p_pot <= public.fn_ca_diamond_economic('bbj_min_pot', v_scope) THEN
    RAISE EXCEPTION 'diamond_jackpot_pot_below_the_payout_floor:%', p_pot USING ERRCODE = '23514';
  END IF;

  v_pool := public.fn_poker_diamond_jackpot_pool_for_table(p_table_id);
  IF v_pool IS NULL THEN
    RAISE EXCEPTION 'diamond_jackpot_pool_absent' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM public.poker_diamond_jackpot_pools WHERE id = v_pool FOR UPDATE;
  v_ref := 'bbjpay:' || p_table_id::text || ':' || p_hand_number::text;

  -- A REPLAY RETURNS WHAT IT PAID THE FIRST TIME AND PAYS NOTHING.
  IF EXISTS (SELECT 1 FROM public.poker_diamond_jackpot_ledger
              WHERE ref = v_ref AND kind = 'payout') THEN
    SELECT jsonb_build_object('replay', true, 'pool_id', v_pool, 'ref', v_ref,
             'paid', -COALESCE(sum(amount), 0),
             'legs', COALESCE(jsonb_agg(jsonb_build_object('role', recipient_role,
                        'user_id', recipient_user_id, 'amount', -amount) ORDER BY id), '[]'::jsonb))
      INTO v_credit FROM public.poker_diamond_jackpot_ledger
     WHERE ref = v_ref AND kind = 'payout';
    RETURN v_credit;
  END IF;

  v_main := public.fn_poker_diamond_jackpot_bank(v_pool, 'main');
  -- B19 is one shares answer per stake: what is paid, and how it divides.
  v_shares := public.fn_ca_diamond_economic_text('bbj_hit_shares', v_scope);
  v_pct  := public.fn_poker_diamond_jackpot_share(v_shares, 1, 'paid');
  -- B19, in whole Diamonds. Every division floors; what no floor could
  -- allocate STAYS IN THE MAIN POOL, because it was never allocated to a
  -- person and the pool is the players' money either way. Nothing is ever
  -- taken from a player to round a number (CLAUDE.md 10.9 condition 3).
  v_paid   := floor(v_main * v_pct / 100)::bigint;
  IF v_paid <= 0 THEN
    RAISE EXCEPTION 'diamond_jackpot_pool_pays_nothing_yet:main=%', v_main USING ERRCODE = '23514';
  END IF;
  v_loser  := floor(v_paid * public.fn_poker_diamond_jackpot_share(v_shares, 1, 'loser')  / 100)::bigint;
  v_winner := floor(v_paid * public.fn_poker_diamond_jackpot_share(v_shares, 1, 'winner') / 100)::bigint;
  v_table_total := v_paid - v_loser - v_winner;

  -- The rest of the table: everybody dealt in who is neither the loser nor the
  -- winner. Horses among them, on the same terms, never filtered out.
  SELECT COALESCE(array_agg(DISTINCT u ORDER BY u), '{}'::uuid[]) INTO v_others
    FROM unnest(COALESCE(p_table_user_ids, '{}'::uuid[])) u
   WHERE u IS DISTINCT FROM p_loser_user_id AND u IS DISTINCT FROM p_winner_user_id;
  v_n := COALESCE(array_length(v_others, 1), 0);
  IF v_n > 0 THEN
    v_each := (v_table_total / v_n)::bigint;
  ELSE
    v_each := 0;
  END IF;
  v_remainder := v_table_total - v_each * v_n;

  -- One credit and one ledger leg per recipient.
  FOR v_rec IN
    SELECT p_loser_user_id AS user_id, 'loser'::text AS role, v_loser AS amount
    UNION ALL SELECT p_winner_user_id, 'winner', v_winner
    UNION ALL SELECT u, 'table', v_each FROM unnest(v_others) u
  LOOP
    CONTINUE WHEN v_rec.amount <= 0;
    v_key := v_ref || ':' || v_rec.role || ':' || v_rec.user_id::text;
    INSERT INTO public.wallet_credit_idempotency(key, user_id, amount)
    VALUES (v_key, v_rec.user_id, v_rec.amount) ON CONFLICT (key) DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 0 THEN
      RAISE EXCEPTION 'diamond_jackpot_credit_key_already_claimed:%', v_key USING ERRCODE = '23505';
    END IF;
    v_credit := public.add_diamonds_to_balance(
      v_rec.user_id, v_rec.amount::integer, 'arena_withdraw',
      'Diamond Arena Bad Beat Jackpot', v_key);
    IF COALESCE((v_credit->>'success')::boolean, false) IS NOT TRUE
       OR NULLIF(v_credit->>'transaction_id', '') IS NULL THEN
      RAISE EXCEPTION 'diamond_jackpot_credit_failed:%', v_credit->>'error' USING ERRCODE = 'P0404';
    END IF;
    INSERT INTO public.poker_diamond_jackpot_ledger(
      pool_id, bank, kind, amount, table_id, hand_number,
      recipient_user_id, recipient_role, wallet_journal_id, ref, note)
    VALUES (v_pool, 'main', 'payout', -v_rec.amount, p_table_id, p_hand_number,
            v_rec.user_id, v_rec.role, (v_credit->>'transaction_id')::uuid, v_ref,
            'bad beat jackpot hit, ' || v_rec.role || ' share');
    v_paid_out := v_paid_out + v_rec.amount;
    v_legs := v_legs || jsonb_build_object('role', v_rec.role, 'user_id', v_rec.user_id,
                                           'amount', v_rec.amount);
  END LOOP;

  IF v_paid_out > v_paid THEN
    RAISE EXCEPTION 'diamond_jackpot_paid_more_than_it_took' USING ERRCODE = '23514';
  END IF;
  IF public.fn_poker_diamond_jackpot_bank(v_pool, 'main') < 0 THEN
    RAISE EXCEPTION 'diamond_jackpot_main_bank_went_negative' USING ERRCODE = '23514';
  END IF;

  RETURN jsonb_build_object(
    'pool_id', v_pool, 'ref', v_ref, 'main_before', v_main, 'payout_percent', v_pct,
    'paid_total', v_paid, 'paid_out', v_paid_out,
    'left_in_main_pool', v_paid - v_paid_out,
    'loser', v_loser, 'winner', v_winner, 'table_total', v_table_total,
    'table_each', v_each, 'table_remainder_left_in_pool', v_remainder,
    'qualifying_hand', public.fn_poker_diamond_jackpot_qualifying_hand(v_variant),
    'legs', v_legs);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_release(p_custody_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_owner uuid;
  v_c public.poker_diamond_custody%ROWTYPE;
  v_prev public.poker_diamond_movements%ROWTYPE;
  v_request jsonb;
  v_credit jsonb;
  v_receipt jsonb;
  v_lot record;
  v_debt_journal uuid;
BEGIN
  IF p_custody_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'invalid_diamond_release' USING ERRCODE = '22023';
  END IF;

  SELECT user_id INTO v_owner
    FROM public.poker_diamond_custody
   WHERE id = p_custody_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'diamond_custody_not_found';
  END IF;

  -- The wallet always locks before its custody, exactly as reserve does.
  PERFORM id FROM public.profiles WHERE id = v_owner FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;
  SELECT * INTO v_c
    FROM public.poker_diamond_custody
   WHERE id = p_custody_id
   FOR UPDATE;

  v_request := jsonb_build_object(
    'action', 'release',
    'custody_id', p_custody_id,
    'user_id', v_owner
  );

  SELECT * INTO v_prev
    FROM public.poker_diamond_movements
   WHERE request_id = p_request_id;
  IF FOUND THEN
    IF v_prev.request <> v_request THEN
      RAISE EXCEPTION 'idempotency_payload_mismatch';
    END IF;
    RETURN v_prev.receipt;
  END IF;

  IF v_c.state = 'released' THEN
    RAISE EXCEPTION 'diamond_custody_already_released';
  END IF;
  -- A DIAMOND TOURNAMENT ENTRY GOES HOME ONLY THROUGH ITS REFUND AUTHORITY
  -- (Phase 8). fn_poker_diamond_tournament_refund names this row in a
  -- transaction-local setting for the one call it makes; any other caller,
  -- service role included, is refused. An entry in play is never releasable.
  IF v_c.purpose = 'tournament_entry'
     AND current_setting('app.poker_diamond_tournament_release', true) IS DISTINCT FROM p_custody_id::text THEN
    RAISE EXCEPTION 'diamond_tournament_entry_requires_refund_authority' USING ERRCODE = '42501';
  END IF;
  -- An ACTIVE tournament entry (activated by the entry door, as the seat
  -- guards P0810-P0812 require) is released whole by its refund authority;
  -- the settlement test below is the cash seat's and stays the cash seat's.
  IF v_c.state <> 'reserved' AND v_c.purpose <> 'tournament_entry' THEN
    IF v_c.state <> 'active' OR v_c.purpose <> 'cash_seat'
       OR v_c.occupancy_id IS NULL OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_c.seat_id AND s.joined_at=v_c.seat_joined_at
            AND s.occupancy_id=v_c.occupancy_id AND s.user_id=v_c.user_id
            AND s.table_id=v_c.target_id AND s.left_at IS NOT NULL
            AND s.stack=v_c.balance) THEN
      RAISE EXCEPTION 'diamond_custody_requires_settlement';
    END IF;
  END IF;

  FOR v_lot IN
    SELECT l.id, r.amount-r.consumed AS amount
      FROM public.poker_diamond_lot_reservations r
      JOIN public.diamond_purchase_lots l ON l.id = r.lot_id
     WHERE r.custody_id = p_custody_id
       AND r.released_at IS NULL
     ORDER BY l.created_at, l.id
     FOR UPDATE OF l
  LOOP
    UPDATE public.diamond_purchase_lots
       SET arena_reserved = arena_reserved - v_lot.amount
     WHERE id = v_lot.id;
  END LOOP;

  UPDATE public.poker_diamond_lot_reservations
     SET released_at = now()
   WHERE custody_id = p_custody_id
     AND released_at IS NULL;

  IF v_c.balance > 0 THEN
  v_credit := public.add_diamonds_to_balance(
    v_owner,
    v_c.balance::integer,
    'arena_withdraw',
    'Released Poker Arena reservation',
    'poker-release:' || p_custody_id || ':' || p_request_id
  );
  IF (v_credit->>'success')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'diamond_release_credit_failed:%', v_credit->>'error';
  END IF;

  ELSE
    SELECT jsonb_build_object('success',true,'new_balance',diamonds,
      'debt_settled',0,'transaction_id',NULL) INTO v_credit
      FROM public.profiles WHERE id=v_owner;
  END IF;

  IF COALESCE((v_credit->>'debt_settled')::bigint, 0) > 0 THEN
    SELECT id INTO v_debt_journal
      FROM public.diamond_transactions
     WHERE user_id = v_owner
       AND reference_id = 'debt-settlement:' || (v_credit->>'transaction_id')
       AND type = 'debt_settlement'
       AND amount = -(v_credit->>'debt_settled')::bigint;
    IF v_debt_journal IS NULL THEN
      RAISE EXCEPTION 'diamond_debt_journal_missing';
    END IF;

    PERFORM public.fn_ca_register_diamond_journal_row(v_debt_journal);
    IF NOT EXISTS (
      SELECT 1
        FROM public.ca_mint_ledger
       WHERE diamond_tx_id = v_debt_journal
         AND action = 'burn'
         AND asset = 'diamonds'
         AND holder_type = 'player'
         AND holder_id = v_owner
         AND amount = (v_credit->>'debt_settled')::bigint
    ) THEN
      RAISE EXCEPTION 'diamond_debt_retirement_missing';
    END IF;
  END IF;

  UPDATE public.poker_diamond_custody
     SET balance = 0,
         state = 'released',
         released_at = now()
   WHERE id = p_custody_id;

  v_receipt := jsonb_build_object(
    'success', true,
    'custody_id', p_custody_id,
    'request_id', p_request_id,
    'amount', v_c.balance,
    'available_balance', (v_credit->>'new_balance')::bigint,
    'custody_balance', 0,
    'debt_settled', (v_credit->>'debt_settled')::bigint,
    'journal_id', v_credit->>'transaction_id'
  );

  INSERT INTO public.poker_diamond_movements(
    request_id, custody_id, user_id, action, amount,
    source_account, destination_account, wallet_journal_id, request, receipt
  ) VALUES (
    p_request_id, p_custody_id, v_owner, 'release', v_c.balance,
    'arena_custody:' || p_custody_id, 'player:' || v_owner,
    (v_credit->>'transaction_id')::uuid, v_request, v_receipt
  );

  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_pay(p_user_id uuid, p_amount numeric, p_idempotency_key text, p_category text, p_tournament_id uuid, p_description text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_arena uuid; v_kind text; v_bank numeric; v_inserted integer; v_drained jsonb; v_credit jsonb; v_e record;
  v_category text := lower(COALESCE(p_category,''));
  v_prior public.poker_diamond_tournament_ledger%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_tournament_id IS NULL OR p_idempotency_key IS NULL
     OR p_amount IS NULL OR p_amount < 1 OR p_amount <> trunc(p_amount) OR p_amount > 2147483647 THEN
    RAISE EXCEPTION 'diamond_tournament_pay_requires_whole_diamonds' USING ERRCODE='22023';
  END IF;
  SELECT t.club_id INTO v_arena FROM public.tournaments t JOIN public.clubs c ON c.id=t.club_id
   WHERE t.id=p_tournament_id AND c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL AND t.union_id IS NULL;
  IF v_arena IS NULL THEN RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE='23514'; END IF;
  v_kind := CASE WHEN v_category='bounty' THEN 'bounty'
                 WHEN v_category='prize' THEN 'prize'
                 ELSE NULL END;
  IF v_kind IS NULL THEN
    -- A refund never reaches this door: the Diamond refund authority returns
    -- entries whole through fn_poker_diamond_release.
    RAISE EXCEPTION 'diamond_tournament_pay_unknown_category:%', v_category USING ERRCODE='22023';
  END IF;

  -- The key is claimed before any Diamond moves, as the chip credit claims it.
  INSERT INTO public.wallet_credit_idempotency(key,user_id,amount)
  VALUES (p_idempotency_key,p_user_id,p_amount) ON CONFLICT (key) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN
    -- DIAMOND PHASE 11: A RETRY GETS ITS FIRST RECEIPT. The key is the
    -- payment's identity. The same payee, event, bank and amount under it is
    -- this payment, already made: it answers as the first delivery did (true)
    -- and moves nothing. Any other use of the key - another payee, event, bank
    -- or amount, or a key another credit claimed - is refused by name, as every
    -- other Diamond door refuses a reused request id. The description is the
    -- payment's label, not its identity.
    SELECT l.* INTO v_prior FROM public.poker_diamond_tournament_ledger l
     WHERE l.idempotency_key='poker-tournament-pay:'||p_idempotency_key;
    IF NOT FOUND
       OR v_prior.kind IS DISTINCT FROM v_kind
       OR v_prior.tournament_id IS DISTINCT FROM p_tournament_id
       OR v_prior.user_id IS DISTINCT FROM p_user_id
       OR v_prior.amount IS DISTINCT FROM p_amount THEN
      RAISE EXCEPTION 'diamond_tournament_pay_key_reused' USING ERRCODE='22023';
    END IF;
    RETURN true;
  END IF;

  -- The bank this payment draws on: a place from the prize bank, a knockout
  -- (its cash half, the champion's own head, the residual) from the bounty
  -- bank. Each is the sum of the entries' parts less what it already paid.
  SELECT * INTO v_e FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id);
  v_bank := CASE WHEN v_kind='bounty' THEN v_e.bounty_balance ELSE v_e.prize_balance END;
  IF v_bank < p_amount THEN
    RAISE EXCEPTION 'diamond_tournament_bank_short' USING ERRCODE='P0404';
  END IF;
  -- A knockout is paid while the event runs, before the terminal opens the
  -- escrow shadow; the shadow is opened here from the Diamond ledger's exact
  -- parts (idempotent, asserted) so the chip shadow never opens itself from a
  -- proportional split at the first bounty.
  PERFORM public.fn_poker_diamond_tournament_open_shadow(p_tournament_id);

  -- The recipient's wallet first (its journal row is what every drained
  -- row's movement carries), then the custody rows, oldest first.
  v_credit := public.add_diamonds_to_balance(
    p_user_id, p_amount::integer, 'arena_withdraw',
    COALESCE(NULLIF(btrim(p_description),''), CASE WHEN v_kind='bounty' THEN 'Tournament bounty' ELSE 'Tournament prize' END),
    'poker-tournament-pay:'||p_idempotency_key);
  IF COALESCE((v_credit->>'success')::boolean,false) IS NOT TRUE OR NULLIF(v_credit->>'transaction_id','') IS NULL THEN
    RAISE EXCEPTION 'diamond_tournament_pay_credit_failed:%', v_credit->>'error' USING ERRCODE='P0404';
  END IF;
  v_drained := public.fn_poker_diamond_tournament_drain(
    p_tournament_id, v_kind, p_amount::bigint, 'poker-tournament-pay:'||p_idempotency_key, 'player:'||p_user_id::text,
    (v_credit->>'transaction_id')::uuid);

  INSERT INTO public.poker_diamond_tournament_ledger(
    tournament_id,arena_id,user_id,custody_id,kind,amount,prize_part,bounty_part,fee_part,
    idempotency_key,wallet_journal_id,request)
  VALUES (p_tournament_id,v_arena,p_user_id,NULL,v_kind,p_amount::bigint,
    CASE WHEN v_kind='prize' THEN p_amount::bigint ELSE 0 END,
    CASE WHEN v_kind='bounty' THEN p_amount::bigint ELSE 0 END,0,
    'poker-tournament-pay:'||p_idempotency_key,(v_credit->>'transaction_id')::uuid,
    jsonb_build_object('kind',v_kind,'credit_key',p_idempotency_key,'drained',v_drained,'description',p_description));

  -- The escrow shadow follows, as a chip payment's wallet row makes it follow.
  IF v_kind='bounty' THEN
    PERFORM public.fn_ca_escrow_apply(p_tournament_id,'diamond bounty',p_bounty_out => p_amount);
  ELSE
    PERFORM public.fn_ca_escrow_apply(p_tournament_id,'diamond prize',p_prize_out => p_amount);
  END IF;

  IF (SELECT prize_balance+bounty_balance+fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id))
     IS DISTINCT FROM public.fn_poker_diamond_tournament_custody(p_tournament_id)::numeric THEN
    RAISE EXCEPTION 'diamond_tournament_escrow_disagrees_with_custody' USING ERRCODE='P0404';
  END IF;
  -- The answer no longer tells a payment from its retry, so the payment names
  -- its key for the one caller that must know: fn_credit_and_log writes the
  -- payout evidence once, on the call that paid. A retry names nothing.
  PERFORM set_config('app.diamond_tournament_pay_claimed', p_idempotency_key, true);
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.fn_wheel_diamond_cards_pick(p_award_id uuid, p_card smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_user uuid:=auth.uid(); a public.wheel_card_awards; v_values integer[]; v_paid integer;
 v_credit jsonb; v_after numeric; v_rate integer:=public.fn_ca_bridge_rate();
BEGIN
 IF v_user IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Spin'); END IF;
 IF p_award_id IS NULL OR p_card IS NULL OR p_card NOT BETWEEN 1 AND 3 THEN
  RETURN jsonb_build_object('ok',false,'error','Choose Card One, Two Or Three'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_award_id::text,94617));
 SELECT * INTO a FROM public.wheel_card_awards WHERE id=p_award_id FOR UPDATE;
 IF a.id IS NULL OR a.user_id IS DISTINCT FROM v_user THEN
  RETURN jsonb_build_object('ok',false,'error','That Card Game Belongs To Another Player'); END IF;
 v_values:=public.fn_wheel_card_values(a.half_diamonds,a.risk_diamonds,a.permutation);
 IF a.status='picked' THEN
  SELECT COALESCE(p.diamonds,0) INTO v_after FROM public.profiles p WHERE p.id=v_user;
  RETURN jsonb_build_object('ok',true,'replayed',true,'award_id',a.id,'spin_id',a.spin_id,
   'picked',a.picked_card,'cards',to_jsonb(v_values),'paid_diamonds',a.paid_diamonds,
   'risk_diamonds',a.risk_diamonds,'balances',jsonb_build_object('diamonds',v_after),
   'fairness',jsonb_build_object('domain','wheel-v4-cards','roll',a.roll,'permutation',a.permutation,
    'server_seed',a.server_seed,'server_seed_hash',a.server_seed_hash,'client_seed',a.client_seed,'nonce',a.nonce));
 END IF;
 IF public.fn_platform_frozen() THEN
  RETURN jsonb_build_object('ok',false,'error','The Platform Is In Its Maintenance Break. Pick Again In A Few Minutes'); END IF;
 IF EXISTS(SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope='wheel' AND f.cleared_at IS NULL) THEN
  RETURN jsonb_build_object('ok',false,'error','The Diamond Wheel Is Paused'); END IF;
 v_paid:=v_values[p_card];
 -- Same lock order as the spin: both wallets by id, then the pool.
 PERFORM 1 FROM public.profiles WHERE id IN(a.owner_id,v_user) ORDER BY id FOR UPDATE;
 UPDATE public.wheel_card_awards SET status='picked',picked_card=p_card,paid_diamonds=v_paid,
   picked_at=transaction_timestamp() WHERE id=a.id RETURNING * INTO a;
 IF v_paid>0 THEN
  PERFORM public.fn_diamond_spin_book(a.owner_id,a.club_id,a.host_id,a.host_kind,v_user,'diamond_prize',-v_paid,
   'wheel-cards:'||a.id||':custody','Diamond Spins: Diamonds Cards');
  v_credit:=public.add_diamonds_to_balance(v_user,v_paid,'transfer','Diamond Spins: Diamonds',
   'wheel-cards:'||a.id,a.owner_id);
  IF COALESCE((v_credit->>'success')::boolean,false) IS NOT TRUE THEN
   RAISE EXCEPTION 'The Diamond Card Prize Credit Failed: %',v_credit->>'error'; END IF;
  IF NOT a.is_welcome THEN
   UPDATE public.wheel_pools SET diamond_float=diamond_float-v_paid,diamonds_paid=diamonds_paid+v_paid,
     updated_at=now() WHERE host_id=a.host_id;
  END IF;
 END IF;
 SELECT COALESCE(p.diamonds,0) INTO v_after FROM public.profiles p WHERE p.id=v_user;
 RETURN jsonb_build_object('ok',true,'replayed',false,'award_id',a.id,'spin_id',a.spin_id,
  'picked',a.picked_card,'cards',to_jsonb(v_values),'paid_diamonds',v_paid,
  'risk_diamonds',a.risk_diamonds,'value_chips',v_paid::numeric/v_rate,
  'balances',jsonb_build_object('diamonds',v_after),
  'fairness',jsonb_build_object('domain','wheel-v4-cards','roll',a.roll,'permutation',a.permutation,
   'server_seed',a.server_seed,'server_seed_hash',a.server_seed_hash,'client_seed',a.client_seed,'nonce',a.nonce));
END $function$

CREATE OR REPLACE FUNCTION public.fn_wheel_spin_core(p_club_id uuid, p_commit_id uuid, p_client_seed text, p_welcome boolean, p_bonus_ticket_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  c_two48 constant numeric := 281474976710656;   -- 2^48
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  cfg public.wheel_configs%ROWTYPE;
  pool public.wheel_pools%ROWTYPE;
  cm public.wheel_seed_commits%ROWTYPE;
  prior public.wheel_spins%ROWTYPE;
  a record;
  v_rate integer := public.fn_ca_bridge_rate();
  v_price integer; v_mult integer; v_intake numeric;
  v_dia_now numeric; v_intake_chips numeric;
  v_owner uuid; v_owner_dia numeric;
  v_bank numeric; v_bank_after numeric;
  v_promo numeric; v_bank_only numeric; v_pay record;
  v_client text := left(btrim(COALESCE(p_client_seed, '')), 64);
  v_nonce bigint; v_hmac bytea; v_roll numeric; v_point numeric;
  v_total integer := 0; v_acc integer := 0;
  v_eligible smallint[] := '{}'; v_locked jsonb := '[]'::jsonb;
  seg record; v_pick record; v_found boolean := false;
  v_value_chips numeric := 0; v_prize_chips numeric := 0; v_prize_dia integer := 0;
  v_today integer; v_last timestamptz;
  v_spendable integer; v_diamonds numeric; v_purchased integer;
  v_lot record; v_remaining integer; v_take integer;
  v_deduct jsonb; v_credit jsonb;
  v_member_after numeric; v_dia_after numeric;
  v_spin_id uuid := gen_random_uuid();
  v_is_fixture boolean := false;
  v_result jsonb;
  v_ticket public.diamond_bonus_spin_tickets;
  -- The welcome budget is a window, not a lifetime total, and a welcome spin is
  -- the whole wheel or it is not offered. Both figures are measured once, up
  -- front, under the config lock that serialises every spin on this host.
  v_welcome_spent numeric := 0; v_welcome_top numeric := 0;
BEGIN
  -- ── who and where ──────────────────────────────────────────────────────────
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In To Spin');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  IF v_rate IS NULL OR v_rate <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Bridge Rate Is Not Set');
  END IF;
  IF length(v_client) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'A Client Seed Is Required');
  END IF;

  -- ── replay: a commit is spent once; the second call returns the first spin ─
  SELECT * INTO prior FROM public.wheel_spins WHERE commit_id = p_commit_id;
  IF prior.id IS NOT NULL THEN
    IF prior.user_id IS DISTINCT FROM v_user THEN
      RETURN jsonb_build_object('ok', false, 'error', 'That Spin Belongs To Another Player');
    END IF;
    IF prior.club_id IS DISTINCT FROM p_club_id OR prior.client_seed IS DISTINCT FROM v_client
       OR prior.is_welcome IS DISTINCT FROM p_welcome OR prior.bonus_ticket_id IS DISTINCT FROM p_bonus_ticket_id THEN
      RETURN jsonb_build_object('ok',false,'error','That Spin Request Does Not Match Its Receipt');
    END IF;
    RETURN public.fn_wheel_spin_result(prior) || jsonb_build_object('replayed', true);
  END IF;

  RETURN jsonb_build_object('ok',false,'error','Refresh Diamond Spins To Use The New Wheel');

  IF p_bonus_ticket_id IS NOT NULL THEN
    IF p_welcome THEN RETURN jsonb_build_object('ok',false,'error','Choose One Free Spin Reward'); END IF;
    SELECT * INTO v_ticket FROM public.diamond_bonus_spin_tickets WHERE id=p_bonus_ticket_id FOR UPDATE;
    IF v_ticket.id IS NULL OR v_ticket.user_id IS DISTINCT FROM v_user THEN
      RETURN jsonb_build_object('ok',false,'error','Claim This Bonus Spin In Daily Bonus First');
    END IF;
    IF v_ticket.redeemed_spin_id IS NOT NULL THEN
      SELECT * INTO prior FROM public.wheel_spins WHERE id=v_ticket.redeemed_spin_id;
      IF prior.user_id=v_user AND prior.club_id=p_club_id AND prior.commit_id=p_commit_id
         AND prior.client_seed=v_client AND prior.bonus_ticket_id=p_bonus_ticket_id AND NOT prior.is_welcome THEN
        RETURN public.fn_wheel_spin_result(prior)||jsonb_build_object('replayed',true);
      END IF;
      RETURN jsonb_build_object('ok',false,'error','That Bonus Spin Was Already Used');
    END IF;
    IF v_ticket.funded_at IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'error','That Bonus Spin Was Already Used');
    END IF;
  END IF;

  IF p_bonus_ticket_id IS NOT NULL THEN
    -- Match the canonical Mint's lock order before taking host/owner rows.
    PERFORM pg_advisory_xact_lock(hashtext('ca_mint_ledger:diamonds'));
  END IF;

  -- ── the freeze and the kill switch, before any money moves ─────────────────
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Platform Is In Its Maintenance Break. Spin Again In A Few Minutes');
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope = 'wheel' AND f.cleared_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Diamond Wheel Is Paused');
  END IF;

  -- ── the host, its table, its pool: one lock serialises every spin on it ────
  SELECT * INTO cfg FROM public.wheel_configs WHERE host_id = v_host FOR UPDATE;
  SELECT * INTO prior FROM public.wheel_spins WHERE commit_id=p_commit_id;
  IF prior.id IS NOT NULL THEN
    IF prior.user_id IS DISTINCT FROM v_user OR prior.club_id IS DISTINCT FROM p_club_id
       OR prior.client_seed IS DISTINCT FROM v_client OR prior.is_welcome IS DISTINCT FROM p_welcome
       OR prior.bonus_ticket_id IS DISTINCT FROM p_bonus_ticket_id THEN
      RETURN jsonb_build_object('ok',false,'error','That Spin Request Does Not Match Its Receipt');
    END IF;
    RETURN public.fn_wheel_spin_result(prior)||jsonb_build_object('replayed',true);
  END IF;
  IF cfg.host_id IS NULL OR NOT cfg.enabled THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Diamond Wheel Is Not Open Here');
  END IF;
  INSERT INTO public.wheel_pools (host_id) VALUES (v_host) ON CONFLICT (host_id) DO NOTHING;
  SELECT * INTO pool FROM public.wheel_pools WHERE host_id = v_host FOR UPDATE;

  SELECT x.* INTO a FROM public.fn_wheel_segments_audit(cfg.segment_version) x;
  IF a.weight_total IS DISTINCT FROM 100000 OR a.spec_rtp IS DISTINCT FROM 0.800000 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Prize Table Failed Its Audit. The Wheel Is Closed Until It Is Fixed');
  END IF;
  SELECT (CASE WHEN p_welcome OR p_bonus_ticket_id IS NOT NULL THEN 100 ELSE cfg.spin_price_diamonds END) / v.spin_price_diamonds INTO v_mult
    FROM public.wheel_segment_versions v WHERE v.version = cfg.segment_version;
  IF p_bonus_ticket_id IS NOT NULL AND cfg.spin_price_diamonds<>100 THEN RETURN jsonb_build_object('ok',false,'error','The 100 Diamond Reward Table Is Unavailable'); END IF;
  v_price  := CASE WHEN p_welcome OR p_bonus_ticket_id IS NOT NULL THEN 100 ELSE cfg.spin_price_diamonds END;
  IF v_mult IS NULL OR v_mult<1 THEN RETURN jsonb_build_object('ok',false,'error','The 100 Diamond Reward Table Is Unavailable'); END IF;
  v_intake := v_price::numeric / v_rate;
  -- THE HOST IS THE HOUSE (Dan 2026-09-10). Nothing is minted: the whole price
  -- is taken in by the host's owner, and the prize is paid out of what the host
  -- holds. The chip side is bounded by the chips this wheel has taken in (this
  -- spin included) plus the host's allowance; the diamond side by the diamonds
  -- it has taken in plus the seed the host put up. Both are "never more than
  -- taken in", stated on the money that actually moved.
  -- A WELCOME SPIN TAKES NOTHING IN (Dan 2026-09-10: the owner "simply receives
  -- no diamonds"). So it adds nothing to the float and nothing to the intake the
  -- paid game's invariant is stated on; its payout is charged to the welcome
  -- budget instead, a few lines below.
  v_dia_now      := CASE WHEN p_welcome THEN 0 ELSE v_price END;
  v_intake_chips := round((pool.intake_diamonds + v_dia_now)::numeric / v_rate, 2);
  v_owner := public.fn_diamond_game_owner(v_host, v_kind);
  IF v_owner IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'This Host Has No Owner Wallet To Pay');
  END IF;

  -- ── the player: member, not a fixture, inside the limits, able to pay ──────
  IF NOT EXISTS (SELECT 1 FROM public.club_members m
                  WHERE m.club_id = p_club_id AND m.user_id = v_user
                    AND COALESCE(m.status, 'active') IN ('active', 'approved')) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Join The Club Before You Spin');
  END IF;
  v_is_fixture := public.fn_ca_is_fixture_account(v_user) OR public.fn_ca_is_cert_account(v_user);
  IF v_is_fixture AND NOT cfg.allow_fixture_accounts THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Certification Accounts Do Not Spin This Wheel');
  END IF;

  -- ── the welcome spin: once per member, ever, and only out of a real budget ─
  IF p_welcome THEN
    IF NOT cfg.welcome_spin_enabled THEN
      RETURN jsonb_build_object('ok', false, 'error', 'There Is No Welcome Spin Here');
    END IF;
    IF COALESCE(cfg.welcome_budget_chips, 0) <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'The Welcome Spin Is Not Funded Here Yet');
    END IF;
    IF v_user = v_owner THEN
      RETURN jsonb_build_object('ok', false, 'error', 'The Host Does Not Take Its Own Welcome Spin');
    END IF;
    -- The unique index is what actually enforces this; the check is here to
    -- answer the player in words rather than with a constraint violation.
    IF EXISTS (SELECT 1 FROM public.wheel_spins s
                WHERE s.host_id = v_host AND s.user_id = v_user AND s.is_welcome) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'You Have Already Taken Your Welcome Spin Here');
    END IF;
    -- A WELCOME SPIN IS THE WHOLE WHEEL OR IT IS NOT OFFERED (2026-09-11).
    -- The budget used to be checked tier by tier, so as the spend approached it
    -- the top prizes locked one after another and the last new members to
    -- arrive were handed a visibly worse wheel than the first ones. A gift that
    -- gets meaner the longer you take to join is not the gift Dan described.
    -- So the budget is asked ONE question before anything is offered: can it
    -- still cover the biggest prize on this table? If it can, every tier is
    -- live. If it cannot, there is no welcome spin here until the window turns.
    -- ONE DEFINITION OF THE QUESTION (2026-09-11). The door, the page and the
    -- entry read all asked it, and the entry read asked a DIFFERENT one, so a
    -- player could be told "Welcome Spin Ready" and then be refused by the
    -- door. There is one helper now and three callers.
    SELECT r.o_spent, r.o_top INTO v_welcome_spent, v_welcome_top
      FROM public.fn_wheel_welcome_room(v_host) r;
    IF v_welcome_spent + v_welcome_top > cfg.welcome_budget_chips THEN
      RETURN jsonb_build_object('ok', false, 'error', 'The Welcome Spins Here Are Gone For Now');
    END IF;
  END IF;
  SELECT * INTO cm FROM public.wheel_seed_commits
   WHERE id = p_commit_id AND user_id = v_user AND consumed_by IS NULL FOR UPDATE;
  IF cm.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Spin Ticket Is Not Yours Or Was Already Used. Open The Wheel Again');
  END IF;
  IF cm.expires_at < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Spin Ticket Expired. Open The Wheel Again');
  END IF;
  SELECT count(*)::integer, max(s.created_at) INTO v_today, v_last
    FROM public.wheel_spins s
   WHERE s.user_id = v_user AND s.host_id = v_host
     AND (s.created_at AT TIME ZONE 'America/Chicago')::date = (now() AT TIME ZONE 'America/Chicago')::date;
  IF v_today >= cfg.max_spins_per_player_per_day THEN
    RETURN jsonb_build_object('ok', false, 'error', format('You Have Reached Today''s Limit Of %s Spins', cfg.max_spins_per_player_per_day));
  END IF;
  IF v_last IS NOT NULL AND now() - v_last < make_interval(secs => cfg.min_seconds_between_spins) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'One Moment Between Spins');
  END IF;
  SELECT COALESCE(p.diamonds, 0) INTO v_diamonds FROM public.profiles p WHERE p.id = v_user;
  v_purchased := public.fn_wheel_purchased_available(v_user);
  v_spendable := CASE WHEN cfg.purchased_only THEN LEAST(v_diamonds, v_purchased)::integer ELSE v_diamonds::integer END;
  IF NOT p_welcome AND p_bonus_ticket_id IS NULL AND v_spendable < v_price THEN
    RETURN jsonb_build_object('ok', false,
      'error', CASE WHEN cfg.purchased_only AND v_diamonds >= v_price
                    THEN 'This Wheel Spins Purchased Diamonds Only'
                    ELSE 'Not Enough Diamonds For A Spin' END,
      'diamonds', v_diamonds, 'spendable', v_spendable, 'spin_price_diamonds', v_price);
  END IF;

  -- ── the host's cover and its owner's diamonds, locked ─────────────────────
  -- The promo wallet pays first and the host's own chip bank stands behind it
  -- (Dan 2026-09-10). v_bank is the two together: what a prize may draw on.
  SELECT c.o_promo, c.o_bank, c.o_cover INTO v_promo, v_bank_only, v_bank
    FROM public.fn_diamond_game_cover_lock(v_host, v_kind) c;
  SELECT COALESCE(p.diamonds, 0) INTO v_owner_dia FROM public.profiles p WHERE p.id = v_owner;

  -- ── eligibility: the affordability gate ────────────────────────────────────
  FOR seg IN SELECT * FROM public.wheel_segments g WHERE g.version = cfg.segment_version ORDER BY g.ord LOOP
    IF seg.kind = 'chips' THEN
      -- There is no welcome branch here any more. The budget was asked about
      -- the WHOLE table before the spin was allowed, so on a welcome spin every
      -- tier is affordable by construction and none of them may be locked for
      -- being expensive. The exposure gate below is the paid wheel's alone: a
      -- welcome spin took nothing in, so it may not lean on what the paid game
      -- took in either.
      IF NOT p_welcome AND pool.chips_paid + seg.amount * v_mult > v_intake_chips + cfg.exposure_allowance_chips THEN
        v_locked := v_locked || jsonb_build_object('ord', seg.ord, 'reason', 'exposure',
                      'unlocks_at', round(pool.chips_paid + seg.amount * v_mult - cfg.exposure_allowance_chips, 2));
        CONTINUE;
      END IF;
      IF v_bank < seg.amount * v_mult THEN
        v_locked := v_locked || jsonb_build_object('ord', seg.ord, 'reason', 'cover', 'unlocks_at', round(seg.amount * v_mult, 2));
        CONTINUE;
      END IF;
    ELSIF seg.kind = 'diamonds' THEN
      -- THE PAID WHEEL'S FLOAT IS NOT THE GIFT'S TO SPEND (audit 2026-09-11).
      -- A welcome diamond prize comes from the owner and is charged to the
      -- welcome budget, which was checked just above. Gating it on the paid
      -- float as well locked tiers a club had every right to give away, and
      -- draining that float for it made the paid wheel pay for the welcome.
      IF NOT p_welcome AND pool.diamond_float + v_dia_now < seg.amount * v_mult THEN
        v_locked := v_locked || jsonb_build_object('ord', seg.ord, 'reason', 'diamond_float',
                      'unlocks_at', round(seg.amount * v_mult - v_dia_now, 0));
        CONTINUE;
      END IF;
      IF v_owner_dia + v_dia_now < seg.amount * v_mult THEN
        v_locked := v_locked || jsonb_build_object('ord', seg.ord, 'reason', 'owner_diamonds',
                      'unlocks_at', round(seg.amount * v_mult, 0));
        CONTINUE;
      END IF;
    END IF;
    v_eligible := v_eligible || seg.ord;
    v_total := v_total + seg.weight;
  END LOOP;
  IF p_bonus_ticket_id IS NOT NULL AND jsonb_array_length(v_locked)>0 THEN
    RETURN jsonb_build_object('ok',false,'error','The Host Must Cover The Whole Bonus Spin Table','locked',v_locked);
  END IF;
  IF v_total <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No Prize Can Be Paid Right Now. Try Again Shortly', 'locked', v_locked);
  END IF;

  -- ── the roll: committed seed, player seed, per-player nonce ────────────────
  SELECT count(*) + 1 INTO v_nonce FROM public.wheel_spins s WHERE s.user_id = v_user;
  v_hmac := extensions.hmac(convert_to(v_client || ':' || v_nonce::text, 'UTF8'),
                            convert_to(cm.server_seed, 'UTF8'), 'sha256');
  v_roll  := (('x' || encode(substring(v_hmac from 1 for 6), 'hex'))::bit(48)::bigint)::numeric;
  v_point := floor(v_roll * v_total / c_two48);
  v_acc := 0;
  FOR seg IN SELECT * FROM public.wheel_segments g
              WHERE g.version = cfg.segment_version AND g.ord = ANY (v_eligible) ORDER BY g.ord LOOP
    v_acc := v_acc + seg.weight;
    IF v_point < v_acc THEN v_pick := seg; v_found := true; EXIT; END IF;
  END LOOP;
  IF NOT v_found THEN
    SELECT * INTO v_pick FROM public.wheel_segments g
     WHERE g.version = cfg.segment_version AND g.ord = v_eligible[array_length(v_eligible, 1)];
  END IF;

  -- ── 1. the spin is paid for, unless it is the welcome ─────────────────────
  -- THE OWNER SIMPLY RECEIVES NO DIAMONDS (Dan 2026-09-10). Not a refund, not a
  -- credit and back out again: on a welcome spin no diamond moves anywhere. The
  -- player pays nothing, the owner takes nothing, and what the host gives up is
  -- exactly the spin price it would have been paid.
  IF p_bonus_ticket_id IS NOT NULL THEN
    BEGIN
      UPDATE public.diamond_bonus_spin_tickets SET club_id=p_club_id,host_id=v_host,host_kind=v_kind,
        owner_id=v_owner,commit_id=p_commit_id,client_seed=v_client,
        funded_at=transaction_timestamp(),mint_op_id='daily-bonus-spin:'||p_bonus_ticket_id::text
       WHERE id=p_bonus_ticket_id RETURNING * INTO v_ticket;
    EXCEPTION WHEN SQLSTATE 'PDS01' THEN
      RETURN jsonb_build_object('ok',false,'error',SQLERRM);
    END;
  ELSIF NOT p_welcome THEN
    v_deduct := public.deduct_diamonds(
      v_user, v_price,
      format('Diamond Wheel Spin (%s Diamonds)', v_price),
      'wheel_spin', 'wheel_spin',
      jsonb_build_object('spin_id', v_spin_id, 'club_id', p_club_id, 'host_id', v_host,
                         'commit_id', p_commit_id, 'segment_version', cfg.segment_version,
                         'recipient_id', v_owner),
      'wheel:' || v_spin_id::text, 0);
    IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Not Enough Diamonds For A Spin',
                                'detail', v_deduct->>'error');
    END IF;
    -- The intake is the host owner's (Dan 2026-09-10): a transfer, not an issuance.
    v_credit := public.add_diamonds_to_balance(v_owner, v_price, 'transfer',
                  format('Diamond Wheel Intake (%s Diamonds)', v_price), 'wheel:' || v_spin_id::text || ':intake', v_user);
    IF COALESCE((v_credit->>'success')::boolean, false) = false THEN
      RAISE EXCEPTION 'fn_wheel_spin_core: the spin price could not be credited to the host owner: %', v_credit->>'error';
    END IF;
    IF cfg.purchased_only THEN
      v_remaining := v_price;
      FOR v_lot IN SELECT * FROM public.diamond_purchase_lots l
                    WHERE l.user_id = v_user AND l.frozen_at IS NULL
                      AND (l.issued - l.consumed - l.refunded) > 0
                    ORDER BY l.created_at, l.id FOR UPDATE LOOP
        EXIT WHEN v_remaining <= 0;
        v_take := LEAST(v_remaining, v_lot.issued - v_lot.consumed - v_lot.refunded);
        UPDATE public.diamond_purchase_lots SET consumed = consumed + v_take WHERE id = v_lot.id;
        v_remaining := v_remaining - v_take;
      END LOOP;
      IF v_remaining > 0 THEN
        RAISE EXCEPTION 'fn_wheel_spin_core: purchased lots could not cover the spin (% short) after the availability check passed', v_remaining;
      END IF;
    END IF;
  END IF;

  -- ── 2. the prize ───────────────────────────────────────────────────────────
  IF v_pick.kind = 'chips' THEN
    v_prize_chips := round(v_pick.amount * v_mult, 2);
    v_value_chips := v_prize_chips;
    IF v_bank < v_prize_chips THEN
      RAISE EXCEPTION 'fn_wheel_spin_core: the host cover % is below the prize % after the gate passed', v_bank, v_prize_chips;
    END IF;
    -- ONE PAYER FOR EVERY CHIP THE DIAMOND GAMES PAY. The promo wallet goes
    -- first and the host's own bank covers whatever is left (Dan 2026-09-10),
    -- journaled from the paying side so each row names the column the chips
    -- left, and the member side stands down so nothing is journaled twice.
    SELECT * INTO v_pay FROM public.fn_diamond_game_pay_chips(
      'wheel_prize', v_host, v_kind, p_club_id, v_user, v_prize_chips,
      'wheel-prize:' || v_spin_id::text,
      format('Diamond Wheel: %s', v_pick.label),
      jsonb_build_object('spin_id', v_spin_id, 'host_id', v_host, 'host_kind', v_kind,
                         'segment_version', cfg.segment_version, 'ord', v_pick.ord,
                         'welcome', p_welcome,'bonus_ticket_id',p_bonus_ticket_id,
                         'entry_funded_by',CASE WHEN p_bonus_ticket_id IS NOT NULL THEN 'mint' ELSE 'player' END));
    v_member_after := v_pay.member_after;
    v_bank_after   := v_pay.cover_after;
    v_promo        := v_pay.promo_after;
    v_bank_only    := v_pay.bank_after;
    v_bank := v_bank_after;
  ELSIF v_pick.kind = 'diamonds' THEN
    v_prize_dia := (v_pick.amount * v_mult)::integer;
    v_value_chips := round(v_prize_dia::numeric / v_rate, 4);
    -- The diamond prize is paid BY THE HOST'S OWNER, out of what the wheel took
    -- in (Dan 2026-09-10). Two transfer legs, one transaction; nothing is issued.
    PERFORM public.fn_diamond_game_pay_diamonds(v_owner, v_user, v_prize_dia,
              format('Diamond Wheel: %s', v_pick.label), 'wheel:' || v_spin_id::text || ':prize');
  END IF;

  -- ── 4. the pool remembers, on the right side of the books ─────────────────
  -- A welcome payout NEVER enters chips_paid. chips_paid is bounded by what the
  -- paid game took in; the welcome is bounded by the budget the host declared.
  -- Two promises, kept apart, both checked below.
  UPDATE public.wheel_pools
     SET spins = spins + CASE WHEN p_welcome THEN 0 ELSE 1 END,
         welcome_spins = welcome_spins + CASE WHEN p_welcome THEN 1 ELSE 0 END,
         intake_diamonds = intake_diamonds + v_dia_now,
         chips_paid = chips_paid + CASE WHEN p_welcome THEN 0 ELSE v_prize_chips END,
         welcome_chips_paid = welcome_chips_paid + CASE WHEN p_welcome THEN v_value_chips ELSE 0 END,
         diamond_float = diamond_float + v_dia_now
                       - CASE WHEN p_welcome THEN 0 ELSE v_prize_dia END,
         diamonds_paid = diamonds_paid + CASE WHEN p_welcome THEN 0 ELSE v_prize_dia END,
         -- constrained_spins is a rate over `spins`, and a welcome spin is not
         -- one of those, so counting it here made the operator's lock rate able
         -- to exceed 1 (audit 2026-09-11).
         constrained_spins = constrained_spins
                           + CASE WHEN NOT p_welcome AND jsonb_array_length(v_locked) > 0 THEN 1 ELSE 0 END,
         updated_at = now()
   WHERE host_id = v_host
   RETURNING * INTO pool;
  IF pool.chips_paid > round(pool.intake_diamonds::numeric / v_rate, 2) + cfg.exposure_allowance_chips THEN
    RAISE EXCEPTION 'fn_wheel_spin_core: chips_paid % would exceed the chips taken in % + allowance % - the gate was bypassed',
      pool.chips_paid, round(pool.intake_diamonds::numeric / v_rate, 2), cfg.exposure_allowance_chips;
  END IF;
  -- The window is what is bounded now, not the lifetime total, and the row for
  -- THIS spin is not written until a few lines below - so the assertion is made
  -- on the figure the gate used plus what this spin just paid. Both were read
  -- under the config lock, so no other spin on this host can have moved them.
  IF p_welcome AND v_welcome_spent + v_value_chips > cfg.welcome_budget_chips THEN
    RAISE EXCEPTION 'fn_wheel_spin_core: the welcome window has paid % against a budget of % - the gate was bypassed',
      v_welcome_spent + v_value_chips, cfg.welcome_budget_chips;
  END IF;

  SELECT COALESCE(p.diamonds, 0) INTO v_dia_after FROM public.profiles p WHERE p.id = v_user;
  IF v_member_after IS NULL THEN
    SELECT COALESCE(m.chip_balance, 0) INTO v_member_after FROM public.club_members m
     WHERE m.club_id = p_club_id AND m.user_id = v_user LIMIT 1;
  END IF;

  INSERT INTO public.wheel_spins
    (id, host_id, host_kind, club_id, user_id, segment_version, spin_price_diamonds, multiplier, diamonds_per_chip,
     commit_id, server_seed_hash, server_seed, client_seed, nonce, roll, weight_total, eligible_ords, locked,
     outcome_ord, outcome_kind, outcome_amount, prize_value_chips, chips_minted, diamond_accrual,
     pool_chips_minted_after, pool_chips_paid_after, pool_diamond_float_after, diamonds_after, member_chips_after,
     is_fixture, is_welcome, bonus_ticket_id)
  VALUES
    (v_spin_id, v_host, v_kind, p_club_id, v_user, cfg.segment_version,
     CASE WHEN p_welcome THEN 0 ELSE v_price END, v_mult, v_rate,
     cm.id, cm.server_seed_hash, cm.server_seed, v_client, v_nonce, v_roll, v_total, v_eligible, v_locked,
     v_pick.ord, v_pick.kind, v_pick.amount * v_mult, v_value_chips, 0, v_dia_now,
     pool.chips_minted, pool.chips_paid, pool.diamond_float, v_dia_after, v_member_after,
     v_is_fixture, p_welcome, p_bonus_ticket_id)
  RETURNING * INTO prior;
  UPDATE public.wheel_seed_commits SET consumed_by = v_spin_id WHERE id = cm.id;

  IF p_bonus_ticket_id IS NOT NULL THEN
    UPDATE public.diamond_bonus_spin_tickets SET redeemed_spin_id=v_spin_id,redeemed_at=transaction_timestamp()
     WHERE id=p_bonus_ticket_id;
  END IF;
  RETURN public.fn_wheel_spin_result(prior) || jsonb_build_object('replayed', false);
END $function$

CREATE OR REPLACE FUNCTION public.send_stream_gift(p_stream_id uuid, p_amount integer, p_message text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sender             uuid := auth.uid();
  v_recipient          uuid;
  v_stream_status      text;
  v_sender_balance     integer;
  v_recipient_balance  integer;
  v_gift_id            uuid;
  v_ref                text := COALESCE(p_reference_id, gen_random_uuid()::text);
  v_cap_check          jsonb;
BEGIN
  -- ── Auth + arg validation ────────────────────────────────────────────────
  IF v_sender IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Amount must be positive');
  END IF;

  -- ── Idempotency guard ────────────────────────────────────────────────────
  -- The rows this function writes are <ref>:sender and <ref>:recipient. Looking for the bare
  -- <ref> found nothing, ever, so a retry with the same reference gifted a second time.
  IF EXISTS (SELECT 1 FROM diamond_transactions WHERE reference_id IN (v_ref, v_ref || ':sender', v_ref || ':recipient')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Duplicate reference_id', 'duplicate', true);
  END IF;

  -- ── Resolve stream + broadcaster ─────────────────────────────────────────
  SELECT broadcaster_id, status INTO v_recipient, v_stream_status
    FROM live_streams WHERE id = p_stream_id;

  IF v_recipient IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Stream not found');
  END IF;
  IF v_stream_status <> 'live' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Stream not live', 'status', v_stream_status);
  END IF;
  IF v_recipient = v_sender THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot gift yourself');
  END IF;

  -- ── GFT-5: anti-farming cap check (unified layer) ────────────────────────
  v_cap_check := public.fn_check_anti_farming_gift_cap(v_sender, v_recipient, p_amount);
  IF NOT (v_cap_check->>'allowed')::boolean THEN
    RETURN jsonb_build_object(
      'success', false,
      'error',   v_cap_check->>'reason',
      'code',    v_cap_check->>'code',
      'cap_check', v_cap_check
    );
  END IF;

  -- ── What may be gifted (ruling 4 with ruling 1) ──────────────────────────
  IF public.fn_ca_giftable_balance(v_sender) < p_amount THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Purchased Diamonds Cannot Be Sent As A Gift',
      'code', 'purchased_diamonds_not_giftable',
      'giftable', public.fn_ca_giftable_balance(v_sender));
  END IF;

  -- ── Lock both profile rows, in uuid order ────────────────────────────────
  -- ORDER BY does not fix the order locks are TAKEN in, so two players gifting each other at
  -- the same moment could deadlock. Locking the lower uuid first is deterministic.
  PERFORM 1 FROM profiles WHERE id = LEAST(v_sender, v_recipient) FOR UPDATE;
  PERFORM 1 FROM profiles WHERE id = GREATEST(v_sender, v_recipient) FOR UPDATE;

  -- ── Atomic balance check + deduct ────────────────────────────────────────
  UPDATE profiles
     SET diamonds        = diamonds - p_amount,
         diamond_balance = COALESCE(diamond_balance, diamonds) - p_amount,
         updated_at      = now()
   WHERE id = v_sender
     AND diamonds >= p_amount
   RETURNING diamonds INTO v_sender_balance;

  IF v_sender_balance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient diamonds');
  END IF;

  -- ── Credit broadcaster ───────────────────────────────────────────────────
  UPDATE profiles
     SET diamonds        = diamonds + p_amount,
         diamond_balance = COALESCE(diamond_balance, diamonds) + p_amount,
         updated_at      = now()
   WHERE id = v_recipient
   RETURNING diamonds INTO v_recipient_balance;

  -- ── Log gift in stream feed ──────────────────────────────────────────────
  INSERT INTO live_gifts (stream_id, sender_id, receiver_id, amount, message)
  VALUES (p_stream_id, v_sender, v_recipient, p_amount, p_message)
  RETURNING id INTO v_gift_id;

  -- ── Sender debit (trigger re-validates) ──────────────────────────────────
  INSERT INTO diamond_transactions (
    user_id, amount, transaction_type, type, source, description,
    balance_after, reference_id, counterparty, issuance_class, metadata
  ) VALUES (
    v_sender, -p_amount, 'spend', 'spend', 'stream_gift',
    'Gift sent in live stream',
    v_sender_balance, v_ref || ':sender',
    'player:' || v_recipient::text, 'transferred',
    jsonb_build_object(
      'stream_id',    p_stream_id,
      'recipient_id', v_recipient,
      'gift_id',      v_gift_id,
      'message',      p_message
    )
  );

  -- ── Recipient credit ─────────────────────────────────────────────────────
  INSERT INTO diamond_transactions (
    user_id, amount, transaction_type, type, source, description,
    balance_after, reference_id, counterparty, issuance_class, metadata
  ) VALUES (
    v_recipient, p_amount, 'earn', 'earn', 'stream_gift',
    'Gift received in live stream',
    v_recipient_balance, v_ref || ':recipient',
    'player:' || v_sender::text, 'transferred',
    jsonb_build_object(
      'stream_id', p_stream_id,
      'sender_id', v_sender,
      'gift_id',   v_gift_id,
      'message',   p_message
    )
  );

  RETURN jsonb_build_object(
    'success',         true,
    'gift_id',         v_gift_id,
    'sender_balance',  v_sender_balance,
    'amount',          p_amount,
    'reference_id',    v_ref
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.send_wallet_diamond_transfer(p_recipient_id uuid, p_amount integer, p_message text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_sender uuid := auth.uid();
  v_previous public.diamond_wallet_transfers%ROWTYPE;
  v_id uuid := gen_random_uuid();
  v_sender_balance integer;
  v_recipient_balance integer;
  v_collateral bigint;
  v_cap jsonb;
  v_debt record;
  v_take integer;
  v_settled integer := 0;
  v_sender_journal uuid;
  v_recipient_journal uuid;
  v_debt_journal uuid;
  v_ref text;
BEGIN
  IF v_sender IS NULL OR NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  IF p_recipient_id IS NULL OR p_recipient_id = v_sender
     OR p_amount IS NULL OR p_amount <= 0
     OR p_reference_id IS NULL
     OR p_reference_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{11,127}$'
     OR length(COALESCE(p_message,'')) > 280 THEN
    RAISE EXCEPTION 'invalid_transfer_request' USING ERRCODE='22023';
  END IF;

  -- Shares the authoritative profile locks used by store spending and custody.
  PERFORM 1 FROM public.profiles WHERE id=LEAST(v_sender,p_recipient_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'transfer_profile_not_found'; END IF;
  PERFORM 1 FROM public.profiles WHERE id=GREATEST(v_sender,p_recipient_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'transfer_profile_not_found'; END IF;

  SELECT * INTO v_previous FROM public.diamond_wallet_transfers
    WHERE sender_id=v_sender AND request_id=p_reference_id;
  IF FOUND THEN
    IF v_previous.recipient_id <> p_recipient_id OR v_previous.amount <> p_amount
       OR v_previous.message IS DISTINCT FROM p_message THEN
      RAISE EXCEPTION 'idempotency_payload_mismatch' USING ERRCODE='22023';
    END IF;
    RETURN to_jsonb(v_previous) || jsonb_build_object('success',true);
  END IF;

  -- Rechecked at the writer, even when the UI selected an accepted friend.
  PERFORM 1 FROM public.friendships
    WHERE status='accepted' AND
      ((user_id=v_sender AND friend_id=p_recipient_id) OR
       (user_id=p_recipient_id AND friend_id=v_sender))
    FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'accepted_friend_required' USING ERRCODE='42501'; END IF;

  v_cap := public.fn_check_anti_farming_gift_cap(v_sender,p_recipient_id,p_amount);
  IF (v_cap->>'allowed')::boolean IS DISTINCT FROM true THEN
    RETURN jsonb_build_object('success',false,'code',v_cap->>'code',
      'error',v_cap->>'reason','cap_check',v_cap);
  END IF;
  SELECT diamonds INTO v_sender_balance FROM public.profiles WHERE id=v_sender;
  SELECT diamonds INTO v_recipient_balance FROM public.profiles WHERE id=p_recipient_id;
  -- Preserve the current refundable-purchase restriction. Held purchased units
  -- are already outside available balance, so do not subtract them twice.
  SELECT COALESCE(sum(GREATEST(issued-consumed-refunded-arena_reserved,0)),0)
    INTO v_collateral FROM public.diamond_purchase_lots WHERE user_id=v_sender;
  IF v_sender_balance IS NULL OR v_sender_balance < p_amount
     OR v_sender_balance::bigint-v_collateral < p_amount THEN
    RETURN jsonb_build_object('success',false,'code','insufficient_transferable_diamonds',
      'error','Only Available Diamonds Outside Purchased Refund Collateral Can Be Sent');
  END IF;
  IF v_recipient_balance IS NULL
     OR v_recipient_balance::bigint+p_amount > 2147483647 THEN
    RAISE EXCEPTION 'recipient_balance_limit';
  END IF;

  -- Same debt treatment as the existing authoritative positive-credit path.
  -- Separate transfer journals retain the actual counterparty, not player:unknown.
  FOR v_debt IN SELECT * FROM public.diamond_debts
    WHERE user_id=p_recipient_id AND settled_at IS NULL
    ORDER BY created_at,id FOR UPDATE
  LOOP
    EXIT WHEN v_settled >= p_amount;
    v_take := LEAST(v_debt.amount,p_amount-v_settled);
    IF v_take = v_debt.amount THEN
      UPDATE public.diamond_debts SET settled_at=now(),settled_by='send_wallet_diamond_transfer'
        WHERE id=v_debt.id;
    ELSE
      UPDATE public.diamond_debts SET amount=amount-v_take WHERE id=v_debt.id;
      INSERT INTO public.diamond_debts(user_id,purchase_id,amount,reason,created_at,settled_at,settled_by)
        VALUES(p_recipient_id,v_debt.purchase_id,v_take,
          v_debt.reason || ' (partial settlement of ' || v_debt.id || ')',
          v_debt.created_at,now(),'send_wallet_diamond_transfer');
    END IF;
    v_settled := v_settled+v_take;
  END LOOP;

  v_ref := 'wallet-transfer:' || v_sender || ':' || p_reference_id;
  INSERT INTO public.diamond_transactions(user_id,amount,type,transaction_type,source,
    description,balance_after,reference_id,counterparty,issuance_class,metadata)
  VALUES(v_sender,-p_amount,'diamond_gift_sent','diamond_gift_sent','wallet_diamond_transfer',
    'Diamonds Sent To A Friend',v_sender_balance-p_amount,v_ref || ':sender',
    'player:' || p_recipient_id,'transferred',
    jsonb_build_object('transfer_id',v_id,'recipient_id',p_recipient_id,'message',p_message))
  RETURNING id INTO v_sender_journal;
  INSERT INTO public.diamond_transactions(user_id,amount,type,transaction_type,source,
    description,balance_after,reference_id,counterparty,issuance_class,metadata)
  VALUES(p_recipient_id,p_amount,'diamond_gift_received','diamond_gift_received','wallet_diamond_transfer',
    'Diamonds Received From A Friend',v_recipient_balance+p_amount,v_ref || ':recipient',
    'player:' || v_sender,'transferred',
    jsonb_build_object('transfer_id',v_id,'sender_id',v_sender,'message',p_message))
  RETURNING id INTO v_recipient_journal;
  IF v_settled > 0 THEN
    INSERT INTO public.diamond_transactions(user_id,amount,type,transaction_type,source,
      description,balance_after,reference_id,counterparty,issuance_class,metadata)
    VALUES(p_recipient_id,-v_settled,'debt_settlement','debt_settlement','debt_settlement',
      'Settled Diamonds Owed After A Reversed Purchase',v_recipient_balance+p_amount-v_settled,
      'debt-settlement:' || v_recipient_journal,'receivable:diamond_debts','spend',
      jsonb_build_object('credit_transaction_id',v_recipient_journal,'transfer_id',v_id))
    RETURNING id INTO v_debt_journal;
    PERFORM public.fn_ca_register_diamond_journal_row(v_debt_journal);
    IF NOT EXISTS(SELECT 1 FROM public.ca_mint_ledger
      WHERE diamond_tx_id=v_debt_journal AND action='burn' AND asset='diamonds'
        AND holder_type='player' AND holder_id=p_recipient_id AND amount=v_settled) THEN
      RAISE EXCEPTION 'diamond_debt_retirement_missing';
    END IF;
  END IF;
  UPDATE public.profiles SET diamonds=v_sender_balance-p_amount,
    diamond_balance=v_sender_balance-p_amount,updated_at=now() WHERE id=v_sender;
  UPDATE public.profiles SET diamonds=v_recipient_balance+p_amount-v_settled,
    diamond_balance=v_recipient_balance+p_amount-v_settled,updated_at=now() WHERE id=p_recipient_id;
  INSERT INTO public.diamond_wallet_transfers(id,sender_id,recipient_id,request_id,amount,message,
    sender_journal_id,recipient_journal_id)
